(() => {'use strict';const $=id=>document.getElementById(id),g=()=>window.gameDebug;
function action(label,fn,disabled=false){const b=document.createElement('button');b.textContent=label;b.disabled=disabled;b.onclick=fn;return b;}
function render(){if(!g())return;const s=g().state,a=g().active(),w=DND.weapon(a,s.level);$('turn-resources').textContent=s.combat?`${a.move} кл. · действие ${a.acted?'−':'✓'} · бонус ${a.bonusUsed?'−':'✓'} · реакция ${a.reactionUsed?'−':'✓'}`:`${a.name} · КД ${a.ac} · ${a.torch?'факел горит':'без факела'}`;$('roll-log').closest('details').hidden=!s.rolls?.length;$('roll-log').textContent=s.rolls?.at(-1)||'Броски и расчёты появятся здесь.';$('initiative').replaceChildren();if(s.combat)for(const id of s.order){const p=[...s.party,...s.enemies].find(p=>p.id===id);if(!p)continue;const b=action(p.name+' '+p.initiative,()=>{},true);b.className='initiative-token '+(s.order[s.cursor]===id?'current':'')+(p.hp<=0?' down':'');$('initiative').append(b)}
$('quick-actions').replaceChildren();const usable=!g().busy&&a.hp>0&&!a.dead;for(const [id,label]of(s.rulesStage>=2?[['dodge','Уклониться'],['dash','Рывок'],['disengage','Отход'],['hide','Скрыться'],['search','Осмотреть']]:[['search','Осмотреть']]))$('quick-actions').append(action(label,()=>g().special(id),!usable||(s.combat&&a.acted)));$('quick-actions').append(action('Снаряжение рук',()=>window.Torches.openHands(),!usable));$('quick-actions').append(action(a.torch?'Погасить факел':'Зажечь факел',()=>g().special('torch'),!usable||!a.torches||!a.hands?.includes('torch')||(s.combat&&a.bonusUsed)));if(a.hands?.includes('torch'))$('quick-actions').append(action('Погасить и убрать',()=>window.Torches.stow(),!usable||(s.combat&&a.bonusUsed)));
if(a.kind===2&&s.rulesStage>=3)$('quick-actions').append(action('Второе дыхание · '+a.secondWind,()=>g().special('secondWind'),!usable||!a.secondWind||(s.combat&&a.bonusUsed)));if(a.kind===1&&a.classId!=='cleric'&&s.rulesStage>=3){for(const [id,label]of[['missile','Волшебная стрела'],['burning','Огненные ладони'],['magearmor','Доспехи мага']])$('quick-actions').append(action(label+' · '+a.slots,()=>g().special(id),!usable||!a.slots||(s.combat&&a.acted)));$('quick-actions').append(action((s.autoShield?'✓ ':'')+'Авто «Щит»',()=>{s.autoShield=!s.autoShield;g().save();render()},!usable));}if(a.kind===0&&!a.classId&&s.rulesStage>=3)$('quick-actions').append(action('Метка охотника · '+a.slots,()=>g().special('mark'),!usable||!a.slots||(s.combat&&a.bonusUsed)));if(a.classId==='cleric')$('quick-actions').append(action('Лечение ран · '+a.slots,()=>g().special('cure'),!usable||!a.slots||!a.hands.includes('empty')||(s.combat&&a.acted)));$('rest-short').disabled=$('rest-long').disabled=s.combat||g().busy;
$('dice-formula').value||= '1d20';$('advantage').value=String(s.advantage||0);$('learning-tip').textContent=['','Шаг 1: выберите клетку и нажмите «Идти». Атака: d20 против КД, затем урон.','Шаг 2: попробуйте уклонение, рывок и отход. Они расходуют действие.','Шаг 3: доступны классовые способности, заклинания и концентрация.'][s.rulesStage||1];$('light-state').textContent=window.visibility?.describe(a)||'';}
window.initRules=()=>{const s=$('dice-type');for(const n of DND.dice){const o=document.createElement('option');o.value=n;o.textContent='d'+n;s.append(o)}s.onchange=()=>{$('dice-formula').value='1d'+s.value};$('dice-submit').onclick=()=>{try{g().freeRoll($('dice-formula').value)}catch(e){$('dice-result').textContent=e.message}};$('dice-history').onclick=()=>g().journal();$('advantage').onchange=e=>{g().state.advantage=+e.target.value;g().save();render()};$('rest-short').onclick=()=>g().special('shortRest');$('rest-long').onclick=()=>g().special('longRest');$('skills').onclick=()=>g().special('skills');$('combat-tools-toggle').onclick=()=>{$('combat-tools').hidden=!$('combat-tools').hidden};render()};window.renderRules=render;
})();
